    [4126] = {n="霍尔雷·黑须", d="把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。", tgo={{"霍尔雷·黑须", "黑须的亲信"}}},
    [4127] = {n="船只的残骸", d="回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。"},
    [4128] = {n="拉格纳·雷酒", d="和拉格纳·雷酒谈一谈。"},
    [4129] = {n="奎恩提斯的技艺", d="把被丢弃的小刀交给羽月要塞的奎恩提斯。"},
    [4130] = {n="心灵占卜术", d="和羽月要塞的基恩诺·火花谈一谈。"},
    [4131] = {n="木爪豺狼人", d="在菲拉斯南部地区的木爪豺狼人营地里寻找信使的下落或者信使的物品。"},
    [4135] = {n="痛苦深渊", d="现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。"},
    [4141] = {n="穆尔金和拉瑞安", d="从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。", tgo={{"血瓣花鞭笞者", "血瓣花掠夺者", "血瓣花猛击者", "血瓣花捕兽者"}}},
    [4142] = {n="造访格雷甘", d="把血瓣花交给菲拉斯的格雷甘·山酒。"},
    [4161] = {n="卡多雷的菜谱", d="为多兰纳尔的扎瑞恩收集7条小蜘蛛腿。", tgo={{"森林蜘蛛", "矿洞蜘蛛", "母蜘蛛", "峭壁潜伏者", "林木潜伏者", "森林潜伏者", "邪恶的夜行蜘蛛", "苔藓阔步者"}}},
    [4182] = {n="黑龙的威胁", d="杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。", tgo={{"黑色小龙"}, {"黑色龙兽"}, {"黑色幼龙"}, {"火鳞龙人"}}},
    [4183] = {n="真正的主人", d="把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。"},
    [4184] = {n="真正的主人", d="到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。\n伯瓦尔在暴风要塞里。"},
    [4185] = {n="真正的主人", d="与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。", tgo={{"女伯爵卡特拉娜·普瑞斯托"}}},
    [4186] = {n="真正的主人", d="把伯瓦尔的命令交给湖畔镇的所罗门镇长。"},
    [4223] = {n="真正的主人", d="和燃烧平原的麦克斯韦尔元帅谈一谈。"},
    [4224] = {n="真正的主人", d="和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。\n你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。", tgo={{"狼狈不堪的约翰"}}},
    [4241] = {n="温德索尔元帅", d="到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。\n狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。"},
    [4243] = {n="找回A-Me 01", d="在安戈洛环形山找到A-Me 01。"},
    [4244] = {n="找回A-Me 01", d="找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。", tgo={{"科朗克", "霜狼伐木机", "雷矛伐木机", "7:XT"}}},
    [4245] = {n="找回A-Me 01", d="将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。"},
    [4262] = {n="征服者派隆", d="杀掉征服者派隆，然后向加琳达复命。\n加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。", tgo={{"征服者派隆"}}},
    [4265] = {n="逃离虫巢", d="将拉斯卡尔安全护送到祖卡什虫巢外。\n回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。"},
    [4266] = {n="羽月将军的欢迎", d="与羽月要塞的珊蒂斯·羽月谈一谈。"},
    [4267] = {n="异种蝎的崛起", d="把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。"},
    [4283] = {n="五十个！", d="奥拉留斯想要50枚黑石徽章。在燃烧平原的兽人身上应该可以找到那些徽章。", tgo={{"黑石士兵", "黑石巫师", "黑石杀戮者", "黑石术士", "黑石军官", "黑石座狼", "灰烬座狼", "流涎的灰烬座狼"}}},
    [4284] = {n="能量水晶", d="收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。", objs={"红色能量水晶", "黄色能量水晶", "绿色能量水晶", "蓝色能量水晶"}},
    [4285] = {n="北部水晶塔", d="在安戈洛尔环形山找到北部水晶塔。", objs={"北部水晶塔"}},
    [4286] = {n="好东西", d="到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。", tgo={{"铁怒监军", "铁怒狱卒", "铁怒卫士", "铁怒步兵", "铁怒士兵", "铁怒医师", "铁怒军官", "暗炉农夫"}}},
    [4287] = {n="东部水晶塔", d="在安戈洛尔环形山找到东部水晶塔。", objs={"东部水晶塔"}},
    [4288] = {n="西部水晶塔", d="在安戈洛尔环形山找到西部水晶塔。", objs={"西部水晶塔"}},
    [4289] = {n="安戈洛的猩猩", d="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。", tgo={{"安戈洛猩猩", "安戈洛猩猩"}, {"安戈洛巨猩猩"}, {"安戈洛大猩猩"}}},
    [4290] = {n="拉克维的食物", d="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。", objs={"新鲜的蛇颈龙肉"}},
    [4291] = {n="拉克维的气味", d="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。", tgo={{"拉克维的配偶"}}},
    [4292] = {n="拉克维的诱饵", d="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。", tgo={{"拉克维"}}},
    [4296] = {n="七贤石板", d="把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。", objs={"七贤石板"}},
    [4301] = {n="强大的尤尔查", d="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。", tgo={{"尤尔查"}}},
    [4321] = {n="分析水晶塔", d="过一会再和科琳说话。"},
    [4341] = {n="卡兰·巨锤", d="去黑石深渊找到卡兰·巨锤。\n国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。"},
    [4421] = {n="碧火萨特", d="杀掉11个碧火魔仆、9个碧火巡影者、9个碧火潜行者和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。", tgo={{"碧火魔仆"}, {"碧火捕猎者"}, {"碧火潜行者"}, {"萨瓦瑟拉斯"}}},
    [4441] = {n="被禁锢的古树", d="到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。", objs={"月泉神殿"}},
    [4442] = {n="净化！", d="过一会儿再与艾瑞丹对话。"},
    [4449] = {n="被锁起来的矮人", d="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。", tgo={{"黑铁地质学家"}, {}}, objs={"奥特兰克花岗岩", "破碎的箱子", "坚固的箱子"}},
    [4450] = {n="塔纳利斯的账本", d="把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。", tgo={{}, {"晶网蜘蛛"}, {}, {"加奎亚"}}, objs={"古德斯迪尔的账本", "破损的箱子"}},
    [4491] = {n="朋友的帮助", d="把林格带回马绍尔营地的斯普拉格·弗劳克身边。\n如果林格晕倒了，就用斯普拉格的水壶让他恢复。"},
    [4492] = {n="走丢了！", d="在火羽山找到林格。"},
    [4493] = {n="异种蝎的远征", d="与加基森的炼金师匹斯特苏格谈一谈。"},
    [4495] = {n="好朋友", d="在北边的洞穴附近找到埃沃隆。"},
    [4496] = {n="擒虫先擒王", d="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tgo={{"格里什异种蝎", "格里什工蝎", "格里什劫掠者", "格里什毒刺蝎", "格里什掘洞蝎", "格里什虫巢卫士", "格里什皇后"}, {}}, objs={"安戈洛土堆"}},
    [4501] = {n="当心翼手龙", d="杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。", tgo={{"翼手龙"}, {"狂怒的翼手龙"}}},
    [4502] = {n="火山的活动", d="到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。", tgo={{"灼热元素", "有生烈焰", "火焰使者", "炽热入侵者", "火焰男爵查尔"}}},
    [4503] = {n="希兹尔的的飞行器", d="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。", tgo={{"幼双帆龙", "双帆龙", "老双帆龙"}, {"小翼手龙", "翼手龙", "狂怒的翼手龙"}}},
    [4504] = {n="极度粘稠的沥青", d="帮加基森的特兰雷克收集12块极度粘稠的沥青。", tgo={{"焦油兽", "焦油潜伏者", "焦油兽王", "焦油爬行者"}}},
    [4581] = {n="凯尼斯·静风", d="把辛德瑞尔的便笺交给林歌神殿里的凯尼斯·静风。"},
    [4681] = {n="搁浅的巨兽", d="在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。", objs={"海龟骨头"}},
    [4722] = {n="搁浅的海龟", d="把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"},
    [4723] = {n="搁浅的海洋生物", d="把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"},
    [4725] = {n="搁浅的海龟", d="把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。"},
    [4726] = {n="雏龙精华", d="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。", objs={"雏龙精华"}},
    [4727] = {n="搁浅的海龟", d="把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"},
    [4728] = {n="搁浅的海洋生物", d="把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"},
    [4730] = {n="搁浅的海洋生物", d="把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"},
    [4731] = {n="搁浅的海龟", d="把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。"},
    [4732] = {n="搁浅的海龟", d="把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"},
    [4733] = {n="搁浅的海洋生物", d="把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"},
    [4740] = {n="通缉：莫克迪普！", d="找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。\n向奥伯丁的哨兵戈琳达·纳希恩报告莫克迪普的死讯。", tgo={{"莫克迪普"}}},
    [4761] = {n="桑迪斯·织风", d="与奥伯丁的桑迪斯·织风谈一谈。"},
    [4762] = {n="壁泉河", d="到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。\n将壁泉河水样交给奥伯丁的桑迪斯·织风。", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="黑木熊怪的堕落", d="在空的净化碗里盛满奥伯丁月亮井的井水。\n在黑木熊怪的北部营地里收集水果、坚果和谷物各一份。\n将水和三种食物混合起来，放置在壁泉河附近的营火边，这样就会召来唤引诱熊怪堕落的萨特。\n取回堕落护符，将它交给奥伯丁的桑迪斯·织风。", objs={"萨巴克希斯的恶魔之包"}},
    [4811] = {n="红色水晶", d="到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。", objs={"神秘的红色水晶"}},
    [4812] = {n="清洗水晶", d="在奥伯丁月亮井中把空水瓶装满，然后调查黑海岸东部山脉的红水晶。", objs={"奥伯丁月亮井"}},
    [4813] = {n="水晶中的碎骨", d="向奥伯丁的哨兵哨兵戈琳达·纳希恩报告你的发现。"},
    [4842] = {n="奇怪的源头", d="根据多诺瓦·雪山的指示行动，然后回到她那里报告。"},
    [4861] = {n="被激怒的枭兽", d="在冬泉谷的南部寻找加隆·石矛的被破坏的营帐，以及他的补给物资。"},
    [4863] = {n="被激怒的枭兽", d="找到加隆·石矛的马车。"},
    [4864] = {n="被激怒的枭兽", d="从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。\n将加隆的补给物资和蓝色羽毛护符交给冬泉谷的加隆·石矛。", tgo={{}, {"疯狂的枭兽", "月光枭兽", "狂暴枭兽", "艾露恩的卫士"}}, objs={"加隆的补给物资"}},
    [4901] = {n="祭坛守护者", d="在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。"},
    [4902] = {n="艾露恩的枭兽", d="与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。"},
    [4906] = {n="更深重的堕落", d="费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。", tgo={{"碧火唤魔者"}, {"碧火背叛者"}, {"碧火欺诈者"}, {"萨瓦里克"}}},
    [4971] = {n="时间问题", d="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。\n杀掉15只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。", tgo={{"时光寄生虫"}}},
    [4984] = {n="大自然的苦楚", d="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", tgo={{"生病的狼"}}},
    [4985] = {n="大自然的苦楚", d="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", tgo={{"生病的灰熊"}}},
    [4986] = {n="雕文橡木枝", d="根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给达纳苏斯的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。"},
    [5021] = {n="迟到总比不到好", d="这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。"},
    [5022] = {n="迟到总比不到好", d="与暴风城的皇家代理人巴瑟罗尔协商，查找到艾玛·费尔斯通的下落。通常在市政厅里都有一个人口普查官。"},
    [5048] = {n="善良的艾玛", d="找到暴风城的艾玛并弄清她是否就是艾玛·费尔斯通。如果是的话，那么她可能想要拿到詹妮丝·费尔斯通给她的包裹。"},
    [5050] = {n="好运护符", d="把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"},
    [5066] = {n="战斗的号角：瘟疫之地！", d="找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"},
    [5082] = {n="冬泉熊怪的威胁", d="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。", tgo={{"冬泉探路者"}, {"冬泉巢穴守卫"}, {"冬泉图腾师"}}},
    [5083] = {n="冬泉火酒", d="将空的火酒瓶交给冬泉谷的多诺瓦·雪山。"},
    [5084] = {n="堕落熊怪", d="搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。"},
    [5085] = {n="神秘的粘液", d="将你的发现报告给多诺瓦·雪山。"},
    [5092] = {n="扫清道路", d="杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。\n然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。", tgo={{"骷髅剥皮者"}, {"被奴役的食尸鬼"}}},
    [5097] = {n="标记哨塔", d="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。\n在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。", tgo={{"安多哈尔一号哨塔"}, {"安多哈尔二号哨塔"}, {"安多哈尔三号哨塔"}, {"安多哈尔四号哨塔"}}},
    [5149] = {n="帕米拉的洋娃娃", d="找到帕米拉的洋娃娃。"},
    [5152] = {n="玛莱恩姑妈", d="与安多哈尔废墟南边的玛莱恩谈一谈。"},
    [5153] = {n="古怪的历史学家", d="把约瑟夫的结婚戒指交给安多哈尔的克罗米。", objs={"约瑟夫·雷德帕斯的纪念碑"}},
    [5154] = {n="达隆郡的历史", d="把《达隆郡的历史》交给安多哈尔的克罗米。", objs={"发霉的书籍"}},
    [5155] = {n="加德纳尔的势力", d="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。", tgo={{"加德纳尔恶犬"}, {"加德纳尔守护者"}, {"加德纳尔精兵"}, {"加德纳尔祭司"}}},
    [5156] = {n="验证腐蚀", d="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", tgo={{"热能野兽"}, {"热能恐兽"}}},
    [5157] = {n="收集堕落之水", d="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。", objs={"加德纳尔月亮井"}},
    [5158] = {n="水之魂的帮助", d="把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。"},
    [5159] = {n="净化过的水", d="把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"},
    [5168] = {n="达隆郡的英雄", d="把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。", objs={"达维的圣契", "雷德帕斯之盾"}},
    [5181] = {n="达隆郡的恶魔", d="将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。", objs={"霍古斯的颅骨", "马杜克的破碎之剑"}},
    [5210] = {n="卡林·雷德帕斯", d="将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。"},
    [5211] = {n="达隆郡的保卫者", d="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", tgo={{"达隆郡居民的灵魂"}}},
    [5215] = {n="瘟疫之锅", d="与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。"},
    [5216] = {n="目标：费尔斯通农场", d="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者拜尔摩"}}},
    [5217] = {n="返回冰风岗", d="把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"},
    [5219] = {n="目标：达尔松之泪", d="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者玛维诺斯"}}},
    [5220] = {n="返回冰风岗", d="把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"},
    [5222] = {n="目标：嚎哭鬼屋", d="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者拉扎奇"}}},
    [5223] = {n="返回冰风岗", d="把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"},
    [5225] = {n="目标：盖罗恩农场", d="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者索瓦斯"}}},
    [5226] = {n="返回冰风岗", d="把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"},
    [5238] = {n="任务完成！"},
    [5241] = {n="卡林叔叔", d="找到卡林·瑞德巴思。"},
    [5244] = {n="凯斯利尔废墟", d="与坠星村的加隆·石矛谈一谈。"},
    [5245] = {n="凯斯利尔的怨灵", d="使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。", objs={"上层精灵遗物碎片"}},
    [5246] = {n="历史的残片", d="在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。", objs={"神圣的上层精灵笔迹"}},
    [5250] = {n="坠星村", d="找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。"},
    [5261] = {n="伊根·派特斯金纳", d="与伊根·派特斯金纳谈一谈。"},
    [5401] = {n="银色黎明委任徽章"},
    [5541] = {n="海格纳的弹药", d="把海格纳的弹药交给丹莫罗的海格纳·重枪。", objs={"弹药箱"}},
    [5542] = {n="恶魔之犬", d="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。", tgo={{"瘟疫幼犬"}, {"瘟疫犬"}, {"狂怒的瘟疫犬"}}},
    [5543] = {n="血染的天空", d="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。", tgo={{"瘟疫蝙蝠"}}},
    [5544] = {n="腐肉虫", d="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。", tgo={{"腐肉虫", "腐肉吞噬者"}}},
    [5545] = {n="木材危机", d="收集8捆木材，把它们交给东谷伐木场的管理员莱琳。", objs={"一捆木柴"}},
    [5601] = {n="小妹妹帕米拉", d="在达隆郡里找到帕米拉·雷德帕斯。"},
    [5713] = {n="一击必杀", d="保护哨兵阿娜莎，然后向灰谷迈斯特拉岗哨的奥奈雅报告。"},
    [5742] = {n="救赎", d="听听提里奥·弗丁要说什么。", tgo={{"提里奥·弗丁"}}},
    [5762] = {n="赫米特·奈辛瓦里", d="将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。"},
    [5781] = {n="遗忘的记忆", d="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。", tgo={{"米库提奥·污血"}}},
    [5845] = {n="失落的荣耀", d="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。", objs={"失落荣耀的象征"}},
    [5846] = {n="爱与家庭", d="到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。"},
    [5848] = {n="爱与家庭", d="到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到\"爱与家庭\"这幅画，它被隐藏在另一幅描绘两个月亮的画之后。\n把这幅画还给提里奥·弗丁。", objs={"未完成的油画"}},
    [5863] = {n="砂槌食人魔", d="加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。", tgo={{"砂槌蛮兵"}, {"砂槌执行者"}, {"掠夺者格玛洛克"}}},
    [5903] = {n="瘟疫与你", d="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。", objs={"大白蚁丘"}},
    [5904] = {n="瘟疫与你", d="到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。"},
    [6001] = {n="身心之力", d="使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。\n任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。", tgo={{"月爪枭兽的灵魂"}}},
    [6004] = {n="未竟的事业", d="杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。", tgo={{"血色医护员"}, {"血色猎人"}, {"血色法师"}, {"血色骑士"}}},
    [6021] = {n="流亡者塞达尔", d="将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。", tgo={{"流亡者塞达尔"}}},
    [6023] = {n="未完的任务", d="杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。", tgo={{"猎人莱德雷"}, {"骑士杜尔根"}}},
    [6024] = {n="哈米亚的请求", d="杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。", tgo={{"渗透者哈米亚"}}},
    [6025] = {n="未完的任务", d="进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。"},
    [6028] = {n="永望镇报告", d="把永望镇报告送给西瘟疫地冰风岗的银色黎明军官普尔哈特。"},
    [6030] = {n="尼古拉斯·瑟伦霍夫公爵", d="将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"},
    [6063] = {n="驯服野兽", d="使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。", tgo={{"树林潜伏者"}}},
    [6064] = {n="驯服野兽", d="使用驯兽棒驯服大型峭壁野猪。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。", tgo={{"大峭壁野猪"}}},
    [6084] = {n="驯服野兽", d="使用驯兽棒驯服雪豹。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。", tgo={{"雪豹"}}},
    [6085] = {n="驯服野兽", d="使用驯服兽棒驯服一头冰爪熊。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。", tgo={{"冰爪熊"}}},
    [6086] = {n="训练野兽", d="与铁炉堡的贝莉亚·雷岩谈一谈。"},
    [6101] = {n="驯服野兽", d="使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。", tgo={{"夜刃捕食者"}}},
    [6102] = {n="驯服野兽", d="使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。", tgo={{"巨翼恶枭"}}},
    [6103] = {n="训练野兽", d="与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。"},
    [6134] = {n="幽灵电浆", d="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。", tgo={{"半人马幽灵"}}},
    [6182] = {n="第一个和最后一个", d="与暴风城的马迪亚斯·肖尔谈一谈，他住在旧城区的兵营里。"},
    [6183] = {n="逝者的荣耀", d="如果你愿意接这个任务，就再和马迪亚斯·肖尔谈一谈。"},
    [6184] = {n="弗林特·沙多摩尔", d="到西瘟疫之地的冰风岗去跟弗林特·沙多摩尔会面。"},
    [6185] = {n="东部的瘟疫", d="搜寻东瘟疫之地，寻找\"凋零者\"的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。", objs={"破碎的人类残骸"}},
    [6341] = {n="泰达希尔的渔业", d="将尼莎的货物交给维斯派塔斯。"},
    [6342] = {n="飞往奥伯丁", d="从角鹰兽管理员维斯派塔斯那里租用一只角鹰兽飞到奥伯丁，然后将尼莎的货物交给莱尔德。"},
    [6343] = {n="飞回泰达希尔", d="将莱尔德的回信交给尼莎·影歌。"},
    [6344] = {n="尼莎·影歌", d="与尼莎·影歌谈一谈。"},
    [6387] = {n="荣誉学员", d="将布洛克的名单交给塞尔萨玛的索格拉姆·伯雷森。"},
    [6388] = {n="格莱斯·瑟登", d="将荣誉锄交给铁炉堡的格莱斯·瑟登。"},
    [6389] = {n="瘟疫与你", d="使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向西瘟疫之地冰风岗的纳萨尼尔·杜马报告。"},
    [6391] = {n="飞往铁炉堡", d="从狮鹫管理员索格拉姆·伯雷森那里租一只狮鹫飞往铁炉堡，然后将布洛克的名单交给铁炉堡的高尼尔·石趾。"},
    [6392] = {n="向布洛克回复", d="从狮鹫管理员格莱斯·瑟登那里租用一头飞往塞尔萨玛的狮鹫，然后将荣誉锄交给塞尔萨玛的布洛克·寻石者。"},
    [6603] = {n="冬泉谷的麻烦！", d="到冬泉谷的温泉附近去找到多诺瓦·雪山。"},
    [6604] = {n="被激怒的枭兽", d="与坠星村的加隆·石矛谈一谈。"},
    [7383] = {n="大地之冠", d="用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。", objs={"神谕林地月亮井"}},
    [7701] = {n="悬赏：工头玛托留斯", d="那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。\n杀死工头玛托留斯，将他的头颅交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。", tgo={{"工头玛托留斯"}}},
    [7722] = {n="绝密配方！", d="在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。", objs={"秘密设计图：炽热助熔剂"}},
    [7723] = {n="该死的手指头！", d="汉瑟尔·重拳让你杀掉20个重型作战傀儡。\n重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。", tgo={{"重型作战傀儡"}}},
    [7724] = {n="熔岩蜘蛛的威胁！", d="汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。\n杀死足够多的灼热熔岩蜘蛛后，回去向灼热峡谷的汉瑟尔·重拳复命。", tgo={{"灼热熔岩蜘蛛"}}},
    [7727] = {n="熏火龙", d="汉瑟尔·重拳让你去杀掉20个熏火龙。\n熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。\n当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。", tgo={{"熏火龙"}}},
    [7728] = {n="被盗：鼓风机和望远镜", d="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。\n你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。", tgo={{"黑铁锻造师"}, {"黑铁哨兵"}}},
    [7729] = {n="工作机会：肃清竞争对手", d="杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。", tgo={{"黑铁工头"}, {"黑铁奴隶贩子"}}},
    [7733] = {n="更高的品质", d="把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。", tgo={{"狂暴的怒痕雪人", "老年怒痕雪人", "残忍的怒痕雪人", "潜伏的深痕雪人"}}},
    [7735] = {n="原始雪人毛皮", d="把原始雪人毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"},
    [7791] = {n="捐献毛料", d="使用／收集：奥特兰克花岗岩、Tattered Chest、破碎的箱子", objs={"奥特兰克花岗岩", "Tattered Chest", "破碎的箱子"}},
    [7793] = {n="捐献丝绸", d="使用／收集：奥特兰克花岗岩、破碎的箱子、坚固的箱子", objs={"奥特兰克花岗岩", "破碎的箱子", "坚固的箱子"}},
    [8360] = {n="跳跳舞，换糖果", d="为旅店老板帕拉曼模仿跳舞动作，作为交换，你将得到一颗雷霆崖奶糖！", tgo={{"旅店老板帕拉"}}},
    [8365] = {n="海盗的帽子！", d="塔纳利斯热砂港的傲慢的店主要你去帮他收集20顶南海海盗帽。", tgo={{"南海海盗", "南海劫掠者", "南海码头工人", "南海流氓", "安德雷·费尔比德", "克雷格·尼哈鲁"}}},
    [8460] = {n="木喉熊怪盟友", d="格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。", tgo={{"死木战士"}, {"死木探险者"}, {"死木园丁"}}},
    [8461] = {n="北方的死木熊怪", d="格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。", tgo={{"死木守卫"}, {"死木复仇者"}, {"死木萨满祭司"}}},
    [8462] = {n="与纳菲恩交谈", d="沿着路去费伍德森林，和名叫纳菲恩的熊怪谈一谈。他站在木喉要塞的入口处。"},
    [8464] = {n="冬泉熊怪的活动", d="萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。", tgo={{"冬泉萨满祭司"}, {"冬泉巢穴守卫"}, {"冬泉巨熊怪"}}},
    [86574] = {n="石爪峰补给运输", d="从巨翼双足飞龙那里收集6份石爪补给品，并将它们交给旅店老板法拉莉亚。", tgo={{"幼年巨翼双足飞龙", "巨翼双足飞龙", "巨翼捕猎者", "雄性巨翼双足飞龙", "巨翼雄兽", "Freewind Post Wyvern"}}},
    [86758] = {n="补上一刀", d="找到并消灭那只名叫刀齿鳄的鳄鱼，把马雷克的刀给带回来。", tgo={{"刀齿鳄"}}},
    [87288] = {n="柔软的夜刃豹皮", d="将6张柔软的夜刃豹毛皮交给阿尔德里亚。", tgo={{"夜刃豹"}}},
    [87760] = {n="神圣潜水员", d="找到一名雷鳞兽王，除掉她，并带回她的深渊统御法杖。", tgo={{"雷鳞兽王"}}},
    [91723] = {n="精密仪器", d="在玉石矿洞消灭8名狗头人地卜师，然后返回阿祖拉之塔，向哈米什·伯格沃特复命。", tgo={{"狗头人地卜师"}}},
    [91732] = {n="好钢", d="从玉石矿洞收集4件采矿工具，然后交给东谷伐木场的哈加尔·洛。", objs={"采矿工具"}},
    [91733] = {n="顺流而下", d="找回从东谷伐木场顺流漂走的浸水的斧头、浸水的锯子和浸水的工具箱，然后交给奥尔敏·佩尔福德。", objs={"浸水的斧头", "浸水的锯子", "浸水的工具箱"}},
    [91740] = {n="呱呱的头颅", d="将呱呱的头颅交给山巅之塔的梅里尔·罗斯。"},
    [91741] = {n="被啃过的书", d="将书归还给帕克斯顿修士。"},
    [91743] = {n="鼠辈泛滥", d="从北郡山谷的狗头人手里夺回8被偷走的书，然后交还给帕克斯顿修士。", tgo={{"狗头人歹徒", "狗头人苦力", "狗头人劳工"}}},
    [91745] = {n="采矿顾问", d="去跟北郡山谷回音山矿洞外的凯尔西·法戈谈谈。"},
    [91752] = {n="着眼大局", d="从寻宝者纳夫手里夺回一袋图画书，然后把袋子交给北郡修道院入口处的治安官玛克布莱德。", tgo={{"寻宝者纳夫"}}},
    [91753] = {n="附魔一课", d="阿祖拉之塔的基塔·费温德需要你收集3份发光的残渣。\n发光的残渣可以通过分解狗头人地卜师掉落的粗制的蜡像来获取。"},
    [91758] = {n="跟上那个狗头人！", d="与北郡修道院后方马厩附近的托德林·斯特恩布雷德交谈。"},
    [91772] = {n="狩猎狗头人", d="沿着狗头人的踪迹追查，带上狗头人追踪工具包，去向闪金镇的治安官杜汉报告你的发现。", objs={"Kobold Tracks"}},
    [91775] = {n="归还书籍", d="找到6本遗失的书和《和元素一起玩》，然后交给治安官杜汉。", tgo={{"尼姆希"}, {"狗头人矿工", "狗头人隧道工"}}},
    [91777] = {n="珍稀书籍", d="取回《好奇小巫师的地卜术》和《奥术详解：用简单的话解释魔法》，并交还给北郡修道院内的帕克斯顿修士。", tgo={{"地貌雕刻师伊普", "狗头人地卜师"}, {"母蜘蛛", "狗头人地卜师"}}},
    [92124] = {n="图书盘点", d="与图书馆中帕克斯顿修士的助手丹尼尔交谈。"},
    [92415] = {n="记住我爱你", d="将染血的信交给暴风城的孤儿监护员奈丁加尔。"},
    [92460] = {n="成年礼", d="在森达尔林地与寻天者罗里安交谈。"},
    [92461] = {n="平衡中的和谐", d="在森达尔林地消灭8只幼年瓦尔德伦。", tgo={{"幼年瓦尔德伦"}}},
    [92462] = {n="虫灾调查", d="在森达尔林地消灭8只烦人的卷云蝇。", tgo={{"烦人的卷云蝇"}}},
    [92463] = {n="卷云蝇后", d="消灭森达尔林地的卷云蝇后。", tgo={{"卷云蝇后"}}},
    [92464] = {n="元素动荡", d="在森达尔林地与雅拉·捕风交谈。"},
    [92465] = {n="煽动者", d="在森达尔林地消灭6个翻滚之风和7名奥拉凯斯信徒。", tgo={{"奥拉凯斯信徒"}, {"翻滚之风"}}},
    [92466] = {n="大地的呼唤", d="将一枚阿基尔印记交给塑风者波罗。", tgo={{"奥拉凯斯蛮兵", "奥拉凯斯信徒", "奥拉凯斯新教徒", "高阶女祭司洛苏娜", "天空祭司安德斯", "指挥官贝尔吉洛斯"}}},
    [92467] = {n="大地的呼唤", d="找到众灵高地，并喝下大地灵契。"},
    [92468] = {n="大地的呼唤", d="将粗糙的石英交给森达尔林地的塑风者波罗。"},
    [92469] = {n="向罗里安复命", d="将奥拉凯斯的消息带给森达尔林地的寻天者罗里安。"},
    [92470] = {n="邪恶的族母", d="在森达尔林地消灭8只乌萨拉食腐者，并收集兽穴之母乌萨娜的徽记。", tgo={{"乌萨拉食腐者"}, {"乌萨娜"}}},
    [92471] = {n="烈风之埃瑟恩", d="在森达尔林地与烈风之埃瑟恩交谈。"},
    [92472] = {n="下一步", d="向申达尔村的治安官阿翁达报到。"},
    [92473] = {n="步步紧逼", d="从森达尔林地瘦弱的乌萨拉身上收集6只瘦弱的乌萨拉之爪。", tgo={{"瘦弱的乌萨拉"}}},
    [92474] = {n="优雅坠落", d="从森达尔林地的瞭望塔顶跳下，使用你的踏空而行能力减缓下落速度。"},
    [92479] = {n="潦草的信件", d="阅读潦草的信件，与北郡修道院的托尔德林·茎刃交谈。"},
    [92481] = {n="A Student of the Arcane", d="Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove."},
    [92482] = {n="The Way of the Hunter", d="Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove."},
    [92483] = {n="隐于暗影", d="阅读简易便笺，然后前往森达尔林地的瞭望塔与阿克利·暮刃交谈。"},
    [92484] = {n="拥抱元素", d="检查嗡鸣回溯水晶，然后前往森达尔林地与塑风者波罗交谈。"},
    [92485] = {n="自然学徒", d="阅读折叠的羊皮纸，然后前往森达尔林地与锡顿·银风交谈。"},
    [92514] = {n="欢迎来到申达尔村", d="在申达尔村与伊拉娅·琥珀风和科里埃拉·平风交谈。", tgo={{"伊拉娅·琥珀风"}, {"科里埃拉·平风"}}},
    [92515] = {n="傲爪的麻烦", d="从申达尔高地的傲爪身上收集10张傲爪的毛皮。", tgo={{"傲爪"}}},
    [92516] = {n="角鹰兽的袭扰", d="在申达尔高地消灭8只幼年角鹰兽、6只角鹰兽保卫者和1只角鹰兽雌兽。", tgo={{"幼年角鹰兽"}, {"角鹰兽保卫者"}, {"角鹰兽雌兽"}}},
    [92517] = {n="法外之徒", d="在申达尔高地消灭10名高地强盗，并除掉他们的首领\"恶风\"本尼克。", tgo={{"高地强盗"}, {"恶风本尼克"}}},
    [92528] = {n="信徒之中", d="在法拉斯村四处转转，打探密教在申达尔高地的意图。", tgo={{"衣柜"}}},
    [92529] = {n="法拉斯村", d="去法拉斯村入口附近向传教士贾萨安报到。\n如果阿基尔印记消失了，可以去申达尔村找萨妮亚·银流重新获取。"},
    [92532] = {n="The Warrior's Path", d="Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower."},
    [92544] = {n="奥拉凯斯暴徒", d="在森达尔林地消灭6个奥拉凯斯蛮兵、4名奥拉凯斯皈依者，以及马尔杜科·碎云。", tgo={{"奥拉凯斯蛮兵"}, {"奥拉凯斯新教徒"}, {"马尔杜科·碎云"}}},
    [92550] = {n="高地之劫", d="前往法拉斯村废墟，消灭6名奥拉凯斯唤暴者、4个活体闪电，并夺取指挥官塞克拉斯的徽记。", tgo={{"奥拉凯斯唤暴者"}, {"活体闪电"}, {"指挥官塞克拉斯"}}},
    [92551] = {n="被偷走的补给品", d="从申达尔高地的法拉斯村收集10包被偷走的申达尔补给品。", tgo={{"奥拉凯斯唤暴者", "奥拉凯斯治疗者", "风暴语者泰尔迪奥", "Galemender Delanea"}}},
    [92553] = {n="补充储藏室", d="从申达尔高地各处的生物身上收集3枚小蛋和8份陆行鸟肉。", tgo={{"大碎尸鸟", "小碎尸鸟", "恐鹫", "碎尸鸟", "山鹫", "巨翼枭", "巨翼恶枭", "巨翼猎枭"}, {"雌性森林陆行鸟", "森林陆行鸟雏鸟", "森林陆行鸟", "凶猛的森林陆行鸟", "巨型平原陆行鸟", "暴躁的平原陆行鸟", "敏捷的平原陆行鸟", "疾风陆行鸟"}}},
    [92595] = {n="塑风者", d="听听伊拉娅·琥珀风要说些什么。", tgo={{"伊拉娅·琥珀风"}}},
    [92598] = {n="天穹视界的天赋", d="在森达尔林地的元素交汇处使用你的天穹视界种族技能。", objs={"Elemental Convergence"}},
    [92640] = {n="非常时期", d="在瓦拉纳尔与瓦伦妮亚·风暴之拳交谈，并听从她的指示。", tgo={{"瓦伦妮亚·风暴之拳"}, {"阿耶莎·晨歌"}, {"伊拉德林·晚风"}}},
    [92642] = {n="切断后勤", d="在阵风浆果低地消灭4名奥拉凯斯治疗者和8名奥拉凯斯斗士。", tgo={{"奥拉凯斯治疗者"}, {"奥拉凯斯斗士"}}},
    [92643] = {n="叛徒", d="在瓦拉纳尔西北方高地入口处的屋子里找到密教叛徒。", tgo={{}, {"死去的邪教徒"}}},
    [92644] = {n="不幸的消息", d="将发光的水晶交给瓦拉纳尔的塔拉尼斯·影歌。"},
    [92645] = {n="解决\"破坏者\"", d="在阵风浆果低地消灭指挥官贝尔吉洛斯。", tgo={{"指挥官贝尔吉洛斯"}}},
    [92679] = {n="血之什一税", d="听阿尔瓦里昂·风野说明情况，然后到风野果园寻找阿米莉亚·风野。", tgo={{"阿米莉亚·风野"}, {"阿尔瓦里昂·风野"}}},
    [92682] = {n="派点用场", d="在风野果园收集10个成熟的风暴苹果，并消灭5个饥饿的强盗。", tgo={{"饥饿的强盗"}, {}}, objs={"成熟的风暴苹果"}},
